class Solution {
public:
    string subStrHash(string s, int power, int modulo, int k, int hashValue) {
        long long p = power, m = modulo, h = 0, pk = 1;
        int n = s.size();
        for (int i = 0; i < k; i++) pk = pk * p % m;
        // Initialize G_{n-k} = val(s[n-k])*p^0 + val(s[n-k+1])*p^1 + ... + val(s[n-1])*p^(k-1)
        long long pp = 1;
        for (int i = n - k; i < n; i++) {
            h = (h + (long long)(s[i] - 'a' + 1) * pp) % m;
            pp = pp * p % m;
        }
        int ans = n - k;
        for (int i = n - k; i >= 0; i--) {
            if (h == hashValue) ans = i;
            if (i > 0) {
                // G_{i-1} = val(s[i-1]) + p*G_i - val(s[i+k-1])*p^k
                h = (h * p + (long long)(s[i - 1] - 'a' + 1)
                     - (long long)(s[i + k - 1] - 'a' + 1) * pk % m
                     + m * 27) % m;
            }
        }
        return s.substr(ans, k);
    }
};
